-- Workflow automation extension: versioned graph definitions and approvals.
CREATE TABLE IF NOT EXISTS public.workflow_versions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),organization_id UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,workflow_id UUID NOT NULL REFERENCES public.workflows(id) ON DELETE CASCADE,version INTEGER NOT NULL,graph JSONB NOT NULL DEFAULT '{}'::jsonb,published_by UUID REFERENCES public.users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(workflow_id,version));
CREATE TABLE IF NOT EXISTS public.workflow_approvals (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),organization_id UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,workflow_run_id UUID NOT NULL REFERENCES public.workflow_runs(id) ON DELETE CASCADE,step_key TEXT NOT NULL,approver_user_id UUID REFERENCES public.users(id) ON DELETE SET NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','approved','rejected','expired')),decision_note TEXT,decided_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE public.workflow_versions ENABLE ROW LEVEL SECURITY;ALTER TABLE public.workflow_approvals ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON public.workflow_versions FOR ALL USING(public.is_organization_member(organization_id)) WITH CHECK(public.is_organization_member(organization_id));
CREATE POLICY tenant_isolation ON public.workflow_approvals FOR ALL USING(public.is_organization_member(organization_id)) WITH CHECK(public.is_organization_member(organization_id));
